import pulp

# Create the problem
model = pulp.LpProblem("Truck_Scheduling", pulp.LpMinimize)

# Data from the problem
trucks = {
    1: [('Hub5', 2), ('Hub6', 1), ('Hub1', 1), ('Hub2', 2), ('Hub4', 6), ('Hub3', 8)],
    2: [('Hub3', 4), ('Hub1', 3), ('Hub4', 9), ('Hub2', 9), ('Hub6', 2), ('Hub5', 9)],
    3: [('Hub2', 8), ('Hub1', 7), ('Hub6', 5), ('Hub3', 1), ('Hub4', 10), ('Hub5', 3)],
    4: [('Hub4', 2), ('Hub2', 10), ('Hub6', 7), ('Hub3', 6), ('Hub1', 4), ('Hub5', 9)],
    5: [('Hub4', 9), ('Hub1', 8), ('Hub6', 9), ('Hub3', 7), ('Hub5', 8), ('Hub2', 5)],
    6: [('Hub2', 8), ('Hub6', 2), ('Hub3', 2), ('Hub1', 8), ('Hub5', 7), ('Hub4', 10)]
}

# Extract all hubs
all_hubs = set()
for truck in trucks.values():
    for hub, _ in truck:
        all_hubs.add(hub)
hubs = list(all_hubs)

# Big M - estimate as sum of all durations
big_M = sum(duration for truck in trucks.values() for _, duration in truck)

# Decision variables
# Start times for each truck at each hub it visits
S = {}
for t in range(1, 7):
    for hub, duration in trucks[t]:
        S[(t, hub)] = pulp.LpVariable(f"S_{t}_{hub}", lowBound=0, cat='Continuous')

# Makespan variable
C_max = pulp.LpVariable("C_max", lowBound=0, cat='Continuous')

# Binary variables for sequencing at each hub
y = {}
for h in hubs:
    for t1 in range(1, 7):
        for t2 in range(1, 7):
            if t1 < t2:
                # Check if both trucks visit this hub
                t1_visits = any(hub == h for hub, _ in trucks[t1])
                t2_visits = any(hub == h for hub, _ in trucks[t2])
                if t1_visits and t2_visits:
                    y[(t1, t2, h)] = pulp.LpVariable(f"y_{t1}_{t2}_{h}", cat='Binary')

# Objective: minimize makespan
model += C_max

# Constraints
# 1. Sequence constraints for each truck
for t in range(1, 7):
    route = trucks[t]
    for i in range(len(route) - 1):
        hub1, dur1 = route[i]
        hub2, dur2 = route[i + 1]
        model += S[(t, hub2)] >= S[(t, hub1)] + dur1

# 2. Hub capacity constraints
for h in hubs:
    for t1 in range(1, 7):
        for t2 in range(1, 7):
            if t1 < t2:
                t1_visits = any(hub == h for hub, _ in trucks[t1])
                t2_visits = any(hub == h for hub, _ in trucks[t2])
                if t1_visits and t2_visits:
                    # Truck t1 precedes t2 at hub h
                    model += S[(t1, h)] + trucks[t1][[hub for hub, _ in trucks[t1]].index(h)][1] <= S[(t2, h)] + big_M * (1 - y[(t1, t2, h)])
                    # Truck t2 precedes t1 at hub h
                    model += S[(t2, h)] + trucks[t2][[hub for hub, _ in trucks[t2]].index(h)][1] <= S[(t1, h)] + big_M * y[(t1, t2, h)]

# 3. Makespan definition
for t in range(1, 7):
    for hub, duration in trucks[t]:
        model += C_max >= S[(t, hub)] + duration

# Solve the problem
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print("Status:", pulp.LpStatus[model.status])
print(f"Optimal makespan: {pulp.value(C_max):.2f}")
print("\nSchedule:")
for t in range(1, 7):
    print(f"\nTruck {t}:")
    for hub, duration in trucks[t]:
        start = pulp.value(S[(t, hub)])
        print(f"  {hub}: start at {start:.2f}, duration {duration}, finishes at {start + duration:.2f}")

# Print hub usage timeline
print("\nHub Usage Timeline:")
for h in hubs:
    print(f"\n{h}:")
    hub_operations = []
    for t in range(1, 7):
        if any(hub == h for hub, _ in trucks[t]):
            idx = [hub for hub, _ in trucks[t]].index(h)
            start = pulp.value(S[(t, h)])
            duration = trucks[t][idx][1]
            hub_operations.append((start, start + duration, t))
    hub_operations.sort()
    for start, end, truck in hub_operations:
        print(f"  Truck {truck}: {start:.2f} - {end:.2f}")

import pulp

# Data from the problem
trucks = [1, 2, 3, 4, 5, 6]
hubs = [1, 2, 3, 4, 5, 6]
stops = [1, 2, 3, 4, 5, 6]

# Sequences: (hub, time)
sequences = {
    1: [(5, 2), (6, 1), (1, 1), (2, 2), (4, 6), (3, 8)],
    2: [(3, 4), (1, 3), (4, 9), (2, 9), (6, 2), (5, 9)],
    3: [(2, 8), (1, 7), (6, 5), (3, 1), (4, 10), (5, 3)],
    4: [(4, 2), (2, 10), (6, 7), (3, 6), (1, 4), (5, 9)],
    5: [(4, 9), (1, 8), (6, 9), (3, 7), (5, 8), (2, 5)],
    6: [(2, 8), (6, 2), (3, 2), (1, 8), (5, 7), (4, 10)]
}

# Extract H[t][j] and P[t][j]
H = {}
P = {}
for t in trucks:
    H[t] = {}
    P[t] = {}
    for idx, (hub, time) in enumerate(sequences[t], start=1):
        H[t][idx] = hub
        P[t][idx] = time

# Big M: sum of all processing times
M = sum(P[t][j] for t in trucks for j in stops)

# Model
model = pulp.LpProblem("TruckScheduling", pulp.LpMinimize)

# Variables
S = {}
for t in trucks:
    for j in stops:
        S[t, j] = pulp.LpVariable(f"S_{t}_{j}", lowBound=0, cat='Continuous')

# Binary sequencing variables for stops at same hub
y_vars = {}
for t1 in trucks:
    for t2 in trucks:
        if t1 >= t2:
            continue
        for j in stops:
            for k in stops:
                if H[t1][j] == H[t2][k]:
                    y_vars[t1, j, t2, k] = pulp.LpVariable(f"y_{t1}_{j}_{t2}_{k}", cat='Binary')

# Makespan variable
C_max = pulp.LpVariable("C_max", lowBound=0, cat='Continuous')

# Objective
model += C_max

# Constraints
# 1. Sequential constraints for each truck
for t in trucks:
    for j in range(1, 6):
        model += S[t, j] + P[t][j] <= S[t, j + 1]

# 2. Makespan definition
for t in trucks:
    model += C_max >= S[t, 6] + P[t][6]

# 3. Hub capacity constraints
for t1 in trucks:
    for t2 in trucks:
        if t1 >= t2:
            continue
        for j in stops:
            for k in stops:
                if H[t1][j] == H[t2][k]:
                    y = y_vars[t1, j, t2, k]
                    model += S[t1, j] + P[t1][j] <= S[t2, k] + M * (1 - y)
                    model += S[t2, k] + P[t2][k] <= S[t1, j] + M * y

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print solution
print("Status:", pulp.LpStatus[model.status])
print("Makespan:", pulp.value(C_max))
print("\nStart times:")
for t in trucks:
    print(f"Truck {t}:", end="")
    for j in stops:
        print(f"  {pulp.value(S[t, j]):.1f}", end="")
    print()

import pulp

# Data from problem
jobs_data = [
    [(5, 8), (4, 7), (1, 4), (2, 8), (3, 8)],  # S1
    [(5, 5), (3, 3), (2, 8), (1, 1), (4, 10)], # S2
    [(2, 1), (1, 9), (5, 2), (3, 2), (4, 7)],  # S3
    [(1, 5), (3, 5), (5, 4), (4, 3), (2, 10)], # S4
    [(3, 6), (2, 7), (1, 3), (4, 6), (5, 7)]   # S5
]

n_jobs = 5
n_ops = 5
machines = [1, 2, 3, 4, 5]  # H1..H5

# Processing times and machine for each operation
p = {}  # p[i][j]
mach = {}  # mach[i][j]
for i in range(n_jobs):
    p[i] = {}
    mach[i] = {}
    for j in range(n_ops):
        mach[i][j] = jobs_data[i][j][0]  # hub number
        p[i][j] = jobs_data[i][j][1]     # hours

# Big-M: sum of all processing times
M = sum(p[i][j] for i in range(n_jobs) for j in range(n_ops))

# Create problem
model = pulp.LpProblem("JobShopScheduling", pulp.LpMinimize)

# Variables
C_max = pulp.LpVariable('C_max', lowBound=0, cat='Continuous')
S = pulp.LpVariable.dicts('Start', 
                          [(i, j) for i in range(n_jobs) for j in range(n_ops)], 
                          lowBound=0, cat='Continuous')

# Binary variables for disjunctive constraints
# We only create them when needed (same machine)
x_vars = {}
for i in range(n_jobs):
    for k in range(n_jobs):
        if i != k:
            for j in range(n_ops):
                for l in range(n_ops):
                    if mach[i][j] == mach[k][l]:
                        x_vars[(i, k, j, l)] = pulp.LpVariable(f'x_{i}_{k}_{j}_{l}', cat='Binary')

# Objective: minimize makespan
model += C_max

# Precedence constraints
for i in range(n_jobs):
    for j in range(n_ops - 1):
        model += S[(i, j)] + p[i][j] <= S[(i, j + 1)]

# Disjunctive constraints
for i in range(n_jobs):
    for k in range(n_jobs):
        if i < k:  # avoid duplicate pairs
            for j in range(n_ops):
                for l in range(n_ops):
                    if mach[i][j] == mach[k][l]:
                        x = x_vars[(i, k, j, l)]
                        # If x=1: i before k
                        model += S[(i, j)] + p[i][j] <= S[(k, l)] + M * (1 - x)
                        model += S[(k, l)] + p[k][l] <= S[(i, j)] + M * x

# Makespan definition
for i in range(n_jobs):
    last_op = n_ops - 1
    model += S[(i, last_op)] + p[i][last_op] <= C_max

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output
print("Status:", pulp.LpStatus[model.status])
print("Minimum makespan:", pulp.value(C_max))
print("\nStart times:")
for i in range(n_jobs):
    print(f"Job {i+1}:", end=" ")
    for j in range(n_ops):
        print(f"Op{j+1}(Hub{mach[i][j]})={pulp.value(S[(i, j)]):.1f}", end=" ")
    print()

print("\nMachine schedules:")
for hub in range(1, 6):
    print(f"\nHub {hub}:")
    ops_on_machine = []
    for i in range(n_jobs):
        for j in range(n_ops):
            if mach[i][j] == hub:
                start = pulp.value(S[(i, j)])
                ops_on_machine.append((start, i, j, p[i][j]))
    ops_on_machine.sort()
    for start, i, j, dur in ops_on_machine:
        print(f"  Job {i+1} Op{j+1}: start {start:.1f}, duration {dur}, finish {start+dur:.1f}")

