import pulp

# Data from the problem
shipments_data = {
    "S1": [("H2", 2), ("H1", 2), ("H3", 6)],
    "S2": [("H2", 7), ("H1", 6), ("H3", 10)],
    "S3": [("H3", 8), ("H1", 9), ("H2", 5)],
}

shipments = list(shipments_data.keys())
hubs = ["H1", "H2", "H3"]

# Step index for each shipment
steps = {s: list(range(len(shipments_data[s]))) for s in shipments}

# Large M
M = 1000

# Model
model = pulp.LpProblem("JobShopMinMakespan", pulp.LpMinimize)

# Decision variables
start = {}
for s in shipments:
    for k in steps[s]:
        start[(s, k)] = pulp.LpVariable(f"start_{s}_{k}", lowBound=0, cat='Continuous')

# Binary precedence variables
# precede[(i,j,h)] = 1 if shipment i precedes shipment j at hub h
precede = {}
for h in hubs:
    for i in shipments:
        for j in shipments:
            if i == j:
                continue
            # We only need one direction, say i < j in alphabetical to avoid duplicate constraints
            if i < j:
                # Check if both i and j use hub h at some step
                i_uses_h = any(shipments_data[i][k][0] == h for k in steps[i])
                j_uses_h = any(shipments_data[j][k][0] == h for k in steps[j])
                if i_uses_h and j_uses_h:
                    precede[(i, j, h)] = pulp.LpVariable(f"precede_{i}_{j}_{h}", cat='Binary')

# Makespan variable
C_max = pulp.LpVariable("C_max", lowBound=0, cat='Continuous')

# Objective: minimize makespan
model += C_max

# Constraints

# 1. Precedence within each shipment
for s in shipments:
    for k in range(len(steps[s]) - 1):
        dur = shipments_data[s][k][1]
        model += start[(s, k)] + dur <= start[(s, k+1)]

# 2. No overlap at each hub
for h in hubs:
    # Find all (shipment, step) pairs that use hub h
    ops_at_h = []
    for s in shipments:
        for k in steps[s]:
            if shipments_data[s][k][0] == h:
                ops_at_h.append((s, k))
    # Add sequencing constraints for each pair in ops_at_h
    for idx1 in range(len(ops_at_h)):
        s1, k1 = ops_at_h[idx1]
        for idx2 in range(idx1 + 1, len(ops_at_h)):
            s2, k2 = ops_at_h[idx2]
            if s1 == s2:
                continue
            # Order s1 and s2 for indexing precede dict
            if s1 < s2:
                p = precede.get((s1, s2, h), None)
                if p is not None:
