    3: [("H3", 8), ("H1", 9), ("H2", 5)]
}

hubs = ["H1", "H2", "H3"]
ship_ids = [1, 2, 3]

# Find all pairs of shipments that share a hub
hub_to_shipments = {h: [] for h in hubs}
for s in ship_ids:
    for hub, _ in shipments[s]:
        hub_to_shipments[hub].append(s)

# Model
model = pulp.LpProblem("JobShopScheduling", pulp.LpMinimize)

# Variables
start_vars = {}
for s in ship_ids:
    for idx, _ in enumerate(shipments[s]):
        start_vars[(s, idx)] = pulp.LpVariable(f"start_s{s}_op{idx}", lowBound=0, cat='Continuous')

# Precedence binary variables: y_{p,q,h} = 1 if shipment p precedes shipment q at hub h
precede_vars = {}
for h in hubs:
    ships_at_hub = hub_to_shipments[h]
    for i in range(len(ships_at_hub)):
        for j in range(len(ships_at_hub)):
            p = ships_at_hub[i]
            q = ships_at_hub[j]
            if p != q:
                precede_vars[(p, q, h)] = pulp.LpVariable(f"precede_{p}_{q}_{h}", cat='Binary')

# Makespan variable
Cmax = pulp.LpVariable("Cmax", lowBound=0, cat='Continuous')

# Objective
model += Cmax

# Constraints
# 1. Precedence within each shipment
for s in ship_ids:
    ops = shipments[s]
    for k in range(len(ops) - 1):
        model += start_vars[(s, k+1)] >= start_vars[(s, k)] + ops[k][1]

# 2. Machine capacity constraints using big-M
M = 1000  # large enough constant
for h in hubs:
    ships_at_hub = hub_to_shipments[h]
    for i in range(len(ships_at_hub)):
        for j in range(len(ships_at_hub)):
            p = ships_at_hub[i]
            q = ships_at_hub[j]
            if p != q:
                # Find operation indices for p and q at hub h
                p_index = None
                q_index = None
                for idx, (hub_name, _) in enumerate(shipments[p]):
                    if hub_name == h:
                        p_index = idx
                        break
                for idx, (hub_name, _) in enumerate(shipments[q]):
                    if hub_name == h:
                        q_index = idx
                        break
                if p_index is None or q_index is None:
                    continue  # shouldn't happen
                p_time = shipments[p][p_index][1]
                q_time = shipments[q][q_index][1]

                # If precede[p,q,h] = 1, then p finishes before q starts
                model += start_vars[(q, q_index)] >= start_vars[(p, p_index)] + p_time - M * (1 - precede_vars[(p, q, h)])
                # If precede[p,q,h] = 0, then q finishes before p starts (so precede[q,p,h] = 1)
                model += start_vars[(p, p_index)] >= start_vars[(q, q_index)] + q_time - M * precede_vars[(p, q, h)]

# 3. Completion time constraints
for s in ship_ids:
    last_op_idx = len(shipments[s]) - 1
    last_op_time = shipments[s][last_op_idx][1]
    model += Cmax >= start_vars[(s, last_op_idx)] + last_op_time

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output
print("Status:", pulp.LpStatus[model.status])
print("Optimal makespan:", pulp.value(Cmax))
print("\nStart times:")
for s in ship_ids:
    for idx in range(len(shipments[s])):
        hub, dur = shipments[s][idx]
