    5: [('D4', 6), ('D7', 3), ('D8', 2), ('D2', 9), ('D5', 6), ('D6', 10), ('D9', 4), ('D1', 2), ('D3', 9)],
    6: [('D2', 1), ('D8', 7), ('D5', 5), ('D7', 9), ('D4', 6), ('D3', 4), ('D9', 10), ('D1', 6), ('D6', 5)],
    7: [('D2', 5), ('D8', 8), ('D7', 1), ('D9', 6), ('D1', 6), ('D5', 4), ('D6', 6), ('D3', 6), ('D4', 6)],
    8: [('D7', 6), ('D4', 1), ('D1', 7), ('D8', 3), ('D5', 2), ('D3', 3), ('D2', 1), ('D9', 9), ('D6', 5)],
    9: [('D4', 5), ('D6', 1), ('D2', 2), ('D5', 8), ('D1', 5), ('D7', 7), ('D3', 4), ('D9', 3), ('D8', 8)]
}

# Extract all distribution centers
centers = set()
for route in truck_routes.values():
    for center, _ in route:
        centers.add(center)

# Decision variables
# S[t][c]: start time of truck t at center c
S = {}
for t in range(1, 10):
    S[t] = {}
    for c in centers:
        S[t][c] = pulp.LpVariable(f'S_{t}_{c}', lowBound=0, cat='Continuous')

# Cmax: makespan
Cmax = pulp.LpVariable('Cmax', lowBound=0, cat='Continuous')

# Binary variables for sequencing at each center
y = {}
for t1 in range(1, 10):
    for t2 in range(1, 10):
        if t1 != t2:
            for c in centers:
                y[(t1, t2, c)] = pulp.LpVariable(f'y_{t1}_{t2}_{c}', cat='Binary')

# Objective: minimize makespan
model += Cmax

# Big-M constant (large enough)
M = 1000

# Constraint 1: Cmax >= completion time of each truck's last operation
for t in range(1, 10):
    route = truck_routes[t]
    last_center, last_time = route[-1]
    model += Cmax >= S[t][last_center] + last_time

# Constraint 2: Precedence constraints along each truck's route
for t in range(1, 10):
    route = truck_routes[t]
    for i in range(len(route) - 1):
        curr_center, curr_time = route[i]
        next_center, next_time = route[i + 1]
        model += S[t][next_center] >= S[t][curr_center] + curr_time

# Constraint 3: No overlap constraints at each distribution center
for c in centers:
    for t1 in range(1, 10):
        for t2 in range(1, 10):
            if t1 != t2:
                # Check if both trucks visit this center
                t1_visits_c = any(center == c for center, _ in truck_routes[t1])
                t2_visits_c = any(center == c for center, _ in truck_routes[t2])

                if t1_visits_c and t2_visits_c:
                    # Get processing times
                    t1_time = next(time for center, time in truck_routes[t1] if center == c)
                    t2_time = next(time for center, time in truck_routes[t2] if center == c)

                    # Either t1 precedes t2 or t2 precedes t1
                    model += S[t1][c] + t1_time <= S[t2][c] + M * (1 - y[(t1, t2, c)])
                    model += S[t2][c] + t2_time <= S[t1][c] + M * y[(t1, t2, c)]

# Constraint 4: Link binary variables (y[t1,t2,c] + y[t2,t1,c] = 1)
for c in centers:
    for t1 in range(1, 10):
        for t2 in range(t1 + 1, 10):
            if t1 != t2:
                t1_visits_c = any(center == c for center, _ in truck_routes[t1])
                t2_visits_c = any(center == c for center, _ in truck_routes[t2])

                if t1_visits_c and t2_visits_c:
                    model += y[(t1, t2, c)] + y[(t2, t1, c)] == 1

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print("Status:", pulp.LpStatus[model.status])
print(f"Optimal Makespan: {pulp.value(Cmax):.2f}")
print("\nSchedule:")
print("-" * 50)

# Create a list of all operations
operations = []
for t in range(1, 10):
    for center, time in truck_routes[t]:
        start_time = pulp.value(S[t][center])
        operations.append((t, center, start_time, time, start_time + time))

# Sort by start time
operations.sort(key=lambda x: x[2])

# Print schedule
for op in operations:
