import pulp

# Data from the problem
routes = {
    1: [('C5', 8), ('C2', 8), ('C4', 5), ('C1', 1), ('C3', 4), ('C6', 9)],
    2: [('C6', 2), ('C2', 5), ('C4', 3), ('C3', 10), ('C5', 7), ('C1', 4)],
    3: [('C3', 6), ('C6', 4), ('C4', 6), ('C1', 8), ('C5', 4), ('C2', 5)],
    4: [('C3', 3), ('C2', 6), ('C6', 1), ('C1', 8), ('C5', 1), ('C4', 1)],
    5: [('C2', 1), ('C1', 6), ('C5', 7), ('C4', 3), ('C6', 4), ('C3', 8)],
    6: [('C4', 7), ('C2', 7), ('C3', 1), ('C5', 7), ('C1', 5), ('C6', 9)]
}

# Map center names to indices 1..6
center_to_idx = {'C1': 1, 'C2': 2, 'C3': 3, 'C4': 4, 'C5': 5, 'C6': 6}
idx_to_center = {v: k for k, v in center_to_idx.items()}

# Preprocess: for each truck, store (center_index, time) for each operation
ops = {}
for truck in range(1, 7):
    ops[truck] = [(center_to_idx[cent], t) for (cent, t) in routes[truck]]

# Model
model = pulp.LpProblem("TruckScheduling", pulp.LpMinimize)

# Decision variables
S = {}
for i in range(1, 7):
    for k in range(1, 7):
        S[(i, k)] = pulp.LpVariable(f"S_{i}_{k}", lowBound=0, cat='Continuous')

C_max = pulp.LpVariable("C_max", lowBound=0, cat='Continuous')

# Binary precedence variables: y[i][i2][j] = 1 if truck i precedes truck i2 at center j
y = {}
trucks = list(range(1, 7))
for i in trucks:
    for i2 in trucks:
        if i >= i2:
            continue
        for j in range(1, 7):
            y[(i, i2, j)] = pulp.LpVariable(f"y_{i}_{i2}_{j}", cat='Binary')

# Objective
model += C_max

# Constraints
# 1. Precedence within each truck
for i in trucks:
    for k in range(1, 6):
        model += S[(i, k)] + ops[i][k-1][1] <= S[(i, k+1)]

# 2. Makespan definition
for i in trucks:
    model += S[(i, 6)] + ops[i][5][1] <= C_max

# 3. Disjunctive constraints for each center
M = 10000  # large constant
for j in range(1, 7):  # for each center
    # Find all trucks that visit this center and their operation index
    visiting = []
    for i in trucks:
        for k in range(1, 7):
            if ops[i][k-1][0] == j:
                visiting.append((i, k))
                break
    # Add disjunctive constraints for each pair
    for idx1 in range(len(visiting)):
        for idx2 in range(idx1+1, len(visiting)):
            i1, k1 = visiting[idx1]
            i2, k2 = visiting[idx2]
            t1 = ops[i1][k1-1][1]
            t2 = ops[i2][k2-1][1]
            # Ensure i1 < i2 for variable indexing
            if i1 < i2:
                var_key = (i1, i2, j)
            else:
                var_key = (i2, i1, j)
                # swap to match variable definition
                i1, i2 = i2, i1
                k1, k2 = k2, k1
                t1, t2 = t2, t1
            # Constraint: if y=1, i1 precedes i2
            model += S[(i1, k1)] + t1 <= S[(i2, k2)] + M * (1 - y[var_key])
            # if y=0, i2 precedes i1
            model += S[(i2, k2)] + t2 <= S[(i1, k1)] + M * y[var_key]

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output results
print("Status:", pulp.LpStatus[model.status])
print("Optimal makespan:", pulp.value(C_max))
print("\nStart times for each truck operation:")
for i in trucks:
    print(f"Truck {i}:", end=" ")
    for k in range(1, 7):
        print(f"{idx_to_center[ops[i][k-1][0]]}:{pulp.value(S[(i, k)]):.1f}", end=" ")
    print()

print("\nCenter schedules:")
for j in range(1, 7):
    print(f"Center {idx_to_center[j]}:", end=" ")
    # Collect all operations at this center
    ops_at_center = []
    for i in trucks:
        for k in range(1, 7):
            if ops[i][k-1][0] == j:
                ops_at_center.append((i, k, pulp.value(S[(i, k)]), ops[i][k-1][1]))
    # Sort by start time
    ops_at_center.sort(key=lambda x: x[2])
    for i, k, start, dur in ops_at_center:
        print(f"T{i}({start:.1f}-{start+dur:.1f})", end=" ")
    print()

