# Create the problem
model = pulp.LpProblem("Job_Shop_Scheduling", pulp.LpMinimize)

# Data from the problem
jobs = ['P1', 'P2', 'P3', 'P4', 'P5']
machines = ['A', 'B', 'C', 'D', 'E']

# Operation sequences for each job: (machine, duration)
operations = {
    'P1': [('B', 1), ('E', 2), ('D', 7), ('A', 5), ('C', 2)],
    'P2': [('E', 4), ('C', 2), ('A', 9), ('B', 5), ('D', 6)],
    'P3': [('B', 10), ('C', 3), ('D', 3), ('E', 1), ('A', 9)],
    'P4': [('E', 7), ('C', 3), ('B', 3), ('A', 9), ('D', 2)],
    'P5': [('B', 3), ('E', 4), ('D', 7), ('A', 6), ('C', 10)]
}

# Big M constant - large enough number
M = 1000

# Decision variables
# Start time for each operation
x = {}
for j in jobs:
    for k in range(5):  # 5 operations per job
        x[(j, k)] = pulp.LpVariable(f"x_{j}_{k}", lowBound=0, cat='Continuous')

# Makespan variable
y_max = pulp.LpVariable("y_max", lowBound=0, cat='Continuous')

# Binary variables for sequencing on machines
z = {}
for j in jobs:
    for k in range(5):
        for i in jobs:
            for l in range(5):
                if j < i:  # Only need one direction to avoid redundancy
                    # Check if operations use the same machine
                    if operations[j][k][0] == operations[i][l][0]:
                        z[(j, k, i, l)] = pulp.LpVariable(f"z_{j}_{k}_{i}_{l}", cat='Binary')

# Objective: minimize makespan
model += y_max

# Constraints
# 1. Makespan definition constraints
for j in jobs:
    last_op_idx = 4  # Index of last operation (0-based)
    model += y_max >= x[(j, last_op_idx)] + operations[j][last_op_idx][1]

# 2. Precedence constraints within each job
for j in jobs:
    for k in range(4):  # 0 to 3 (last operation doesn't have a next one)
        model += x[(j, k+1)] >= x[(j, k)] + operations[j][k][1]

# 3. Machine capacity constraints
for j in jobs:
    for k in range(5):
        for i in jobs:
            for l in range(5):
                if j < i and operations[j][k][0] == operations[i][l][0]:
                    # Either j,k precedes i,l or i,l precedes j,k
                    model += x[(i, l)] >= x[(j, k)] + operations[j][k][1] - M * (1 - z[(j, k, i, l)])
                    model += x[(j, k)] >= x[(i, l)] + operations[i][l][1] - M * z[(j, k, i, l)]

# Solve the problem
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print("Status:", pulp.LpStatus[model.status])
