import pulp

# Define offices
offices = ['A', 'B', 'G', 'D', 'E']  # A=Alpha, B=Beta, G=Gamma, D=Delta, E=Epsilon

# Travel durations in minutes (as given in the problem)
times = {
    ('A', 'B'): 63.4,
    ('A', 'G'): 40.6,
    ('A', 'D'): 90.4,
    ('A', 'E'): 66.0,
    ('B', 'G'): 103.3,
    ('B', 'D'): 153.8,
    ('B', 'E'): 116.7,
    ('G', 'D'): 52.9,
    ('G', 'E'): 41.6,
    ('D', 'E'): 74.3,
}
# Make symmetric (travel time is the same in both directions)
for (i, j), t in list(times.items()):
    times[(j, i)] = t

# Create the problem
model = pulp.LpProblem("TSP", pulp.LpMinimize)

# Binary variables x[i][j] = 1 if we travel directly from i to j
x = {}
for i in offices:
    for j in offices:
        if i != j:
            x[(i, j)] = pulp.LpVariable(f"x_{i}_{j}", cat='Binary')

# MTZ variables to eliminate subtours
u = {}
for i in offices:
    u[i] = pulp.LpVariable(f"u_{i}", lowBound=0, upBound=len(offices)-1, cat='Continuous')

# Objective: minimize total travel time
model += pulp.lpSum([times[(i, j)] * x[(i, j)] for i in offices for j in offices if i != j])

# Constraints: each office has exactly one incoming edge
for j in offices:
    model += pulp.lpSum([x[(i, j)] for i in offices if i != j]) == 1

# Constraints: each office has exactly one outgoing edge
for i in offices:
    model += pulp.lpSum([x[(i, j)] for j in offices if i != j]) == 1

# MTZ subtour elimination constraints
for i in offices:
    for j in offices:
        if i != j and i != 'A' and j != 'A':
            model += u[i] - u[j] + (len(offices) - 1) * x[(i, j)] <= len(offices) - 2

# Additional MTZ constraints to handle start/end node
for j in offices:
    if j != 'A':
        model += u[j] >= 1 + x[('A', j)] - (len(offices) - 1) * (1 - x[('A', j)])
        model += u[j] <= (len(offices) - 1) - (len(offices) - 2) * x[('A', j)]

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Display solution
print("Status:", pulp.LpStatus[model.status])
if pulp.LpStatus[model.status] == 'Optimal':
    print("Total travel time (minutes):", pulp.value(model.objective))

    # Extract the tour starting from Alpha (A)
    current = 'A'
    tour = ['A']
    visited = {'A'}

    while len(tour) < len(offices):
        for j in offices:
            if j != current and pulp.value(x[(current, j)]) > 0.5:
                if j not in visited:
                    tour.append(j)
                    visited.add(j)
                    current = j
                    break

    print("\nOptimal tour:")
    print(" -> ".join(tour) + " -> A")
    print(f"\nTotal duration: {pulp.value(model.objective):.1f} minutes")

    # Verify the tour by calculating its total time
    total = 0
    for i in range(len(tour) - 1):
        total += times[(tour[i], tour[i+1])]
    total += times[(tour[-1], 'A')]
    print(f"Verified total: {total:.1f} minutes")
else:
    print("No optimal solution found.")
    print("Current objective value:", pulp.value(model.objective))

import pulp

# Problem data
hubs = [1, 2, 3, 4, 5, 6, 7]
n = len(hubs)

# Distance matrix
dist = {}
dist[(1, 2)] = 99.5
dist[(1, 3)] = 79.5
dist[(1, 4)] = 30.9
dist[(1, 5)] = 33.5
dist[(1, 6)] = 96.2
