dist[(3, 6)] = 174.3
dist[(3, 7)] = 55.2
dist[(4, 5)] = 50.0
dist[(4, 6)] = 127.0
dist[(4, 7)] = 22.7
dist[(5, 6)] = 97.4
dist[(5, 7)] = 62.0
dist[(6, 7)] = 120.2

# Make symmetric
for i, j in list(dist.keys()):
    dist[(j, i)] = dist[(i, j)]

# Model
model = pulp.LpProblem("TSP", pulp.LpMinimize)

# Variables
x = {}
for i in hubs:
    for j in hubs:
        if i != j:
            x[(i, j)] = pulp.LpVariable(f"x_{i}_{j}", cat='Binary')

# Objective
model += pulp.lpSum(dist[(i, j)] * x[(i, j)] for i in hubs for j in hubs if i < j)

# Degree constraints
for i in hubs:
    model += pulp.lpSum(x[(i, j)] for j in hubs if j != i) == 2

# MTZ variables
u = {}
for i in hubs:
    if i == 1:
        u[i] = 0  # fixed
    else:
        u[i] = pulp.LpVariable(f"u_{i}", lowBound=2, upBound=n)

# MTZ constraints for i, j >= 2, i != j
for i in range(2, n+1):
    for j in range(2, n+1):
        if i != j:
            model += u[i] - u[j] + n * x[(i, j)] <= n - 1

# Symmetry constraints (optional, but ensures x_ij = x_ji implicitly by objective and degree)
# Actually, we don't enforce symmetry explicitly because x[i,j] and x[j,i] are independent.
# But in TSP, both represent the same edge, so we should force them equal.
# Instead, we can create variables only for i < j and adjust constraints.
# Let's redo variables for i<j only, and use both directions in constraints.

# --- Rebuilding with i<j variables ---
model = pulp.LpProblem("TSP", pulp.LpMinimize)

# Variables for i<j
x = {}
for i in hubs:
    for j in hubs:
        if i < j:
            x[(i, j)] = pulp.LpVariable(f"x_{i}_{j}", cat='Binary')

# Objective
model += pulp.lpSum(dist[(i, j)] * x[(i, j)] for i in hubs for j in hubs if i < j)

# Degree constraints: sum_{j>i} x_ij + sum_{j<i} x_ji = 2
for i in hubs:
    total = pulp.lpSum(x[(min(i, j), max(i, j))] for j in hubs if j != i)
    model += total == 2

# MTZ variables
u = {}
for i in hubs:
    if i == 1:
        u[i] = 0
    else:
        u[i] = pulp.LpVariable(f"u_{i}", lowBound=2, upBound=n)

# MTZ constraints for i,j >=2, i != j
for i in range(2, n+1):
    for j in range(2, n+1):
        if i != j:
            if i < j:
                model += u[i] - u[j] + n * x[(i, j)] <= n - 1
            else:
                # x[(j, i)] is the variable since j < i
                model += u[i] - u[j] + n * x[(j, i)] <= n - 1

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output
print("Status:", pulp.LpStatus[model.status])
print("Optimal tour distance:", pulp.value(model.objective))
print("Edges in tour:")
for i in hubs:
    for j in hubs:
        if i < j and pulp.value(x[(i, j)]) > 0.5:
